def reverse_string(s):
    chars = list(s)

    def reverse(left, right):
        if left >= right:
            return
        chars[left], chars[right] = chars[right], chars[left]
        reverse(left + 1, right - 1)

    reverse(0, len(chars) - 1)
    return "".join(chars)

