def quick_sort(nums):
    def partition(low, high):
        pivot = nums[low]
        i, j = low, high
        while i < j:
            while i <= high - 1 and nums[i] <= pivot:
                i += 1
            while j >= low + 1 and nums[j] > pivot:
                j -= 1
            if i < j:
                nums[i], nums[j] = nums[j], nums[i]
        nums[low], nums[j] = nums[j], nums[low]
        return j

    def sort(low, high):
        if low < high:
            p = partition(low, high)
            sort(low, p - 1)
            sort(p + 1, high)

    sort(0, len(nums) - 1)
    return nums
